import XCTest

final class TapperUITests: XCTestCase {
    func testOpenPostInApp() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        let openButton = springboard.alerts.buttons["Open"]
        if openButton.waitForExistence(timeout: 15) {
            openButton.tap()
        }

        XCTAssertTrue(app.wait(for: .runningForeground, timeout: 30) || app.state == .runningForeground)
        sleep(6)
    }
}

